const GALL = 'Gallifant J, Kistler EA, Nakayama LF, et al., "Disparity dashboards: an evaluation of the literature and framework for health equity improvement," Lancet Digital Health 2023 (PMC10639125): "only six evaluated the use of a disparity dashboard as part of a wider process to identify clinical disparities, hypothesize potential interventions, or track progress to a given goal." One review, not "a body of research [that] has converged". The paper does not mention Moffitt; Moffitt\'s Disparities Dashboard (clinical metrics stratified by race, ethnicity, gender, language preference) is described by Quality Interactions (qualityinteractions.com/blog/what-are-leading-organizations-doing-to-achieve-health-equity) and Moffitt\'s 2020 diversity report.';
const CMSFW = 'CMS Framework for Health Equity 2022-2032 (cms.gov/files/document/cms-framework-health-equity.pdf): Priority 2 = "Assess Causes of Disparities Within CMS Programs, and Address Inequities in Policies and Operations to Close Gaps" — a commitment about CMS\'s own programs, not a call on other organizations.';
const RUSH6 = RUSH + ' Catholic Health World, 1 Oct 2019 ("Chicago hospitals unite to address socioeconomic needs of West Side residents"): West Side ConnectED = AMITA Saints Mary and Elizabeth, University of Illinois Hospital, Rush, Mount Sinai; seven-question ED screening tool; Catholic Charities convened and linked ~30 partner agencies; funded by West Side United and IHA. AMA ("From screening to shelves") — Rush screens patients routinely and partners with the Greater Chicago Food Depository. "CommunityHealth" as a Rush screening partner not found; no source says the West Side Anchor Committee was formed to act on Rush screening data.';
const L6_RUSH_OLD = 'Rush University Medical Center\'s SDOH screening effort, built with community partners including Catholic Charities, the Greater Chicago Food Depository, and CommunityHealth (Chicago\'s largest free clinic), did not stop at collecting screening data. Rush formed a West Side Anchor Committee explicitly to convert what the screening and stratified quality data showed into standing operating processes — shared goals, common referral pathways, and joint investment decisions with those community partners.';
const L6_RUSH_NEW = 'Rush University Medical Center screens patients routinely for social needs such as housing, food access, and violence, and works with the Greater Chicago Food Depository on food programs. In West Side ConnectED, Rush, the University of Illinois Hospital, AMITA Health Saints Mary and Elizabeth Medical Center, and Mount Sinai Hospital share a seven-question emergency-department screening tool, and Catholic Charities linked the hospitals to about 30 partner agencies ready to take referrals. Inside Rush, an Anchor Mission committee organized in January 2017 sets targets for local hiring, career pathways, local spending, and volunteering and reports to senior leadership twice a year, and a Health Equity Governance Committee steers improvement work on inequities in patient outcomes (Ansell et al., NEJM Catalyst, 2021).';
OPS.push(
  { id: 'hea-from-score-to-action', key: 'l6s2p1', verdict: 'INACCURATE', claim: '"A body of published research on disparity dashboards has converged on a consistent finding" (one 2023 review)', sources: GALL,
    pairs: [['A body of published research on disparity dashboards has converged on a consistent finding: dashboards that stratify data by race, ethnicity, or other subgroup are increasingly common, but dashboards demonstrably tied to a specific accountability structure — someone whose job it is to act when a gap appears — are much rarer.',
      'A 2023 Lancet Digital Health review of the disparity-dashboard literature (Gallifant et al.) found that dashboards stratifying data by race, ethnicity, or other subgroup are increasingly common, but only six of the studies it evaluated used a dashboard as part of a wider process to identify disparities, hypothesize interventions, or track progress toward a goal. Dashboards tied to someone whose job it is to act when a gap appears are the exception.']],
    mirrorPairs: [['A body of published research on disparity dashboards has converged on a consistent finding: dashboards that stratify data by race, ethnicity, or other subgroup are common, but dashboards that are demonstrably tied to a specific accountability structure — someone whose job it is to act when a gap appears — are much rarer.',
      'A 2023 Lancet Digital Health review of the disparity-dashboard literature (Gallifant et al.) found that stratified dashboards are common, but only six of the studies it evaluated used a dashboard as part of a wider process to identify disparities, hypothesize interventions, or track progress toward a goal. Dashboards tied to someone whose job it is to act when a gap appears are the exception.'],
      ['The consistent finding is that stratified dashboards are common, but ones tied to a real accountability structure that acts on the data are much rarer', 'A 2023 Lancet Digital Health review found stratified dashboards common but few embedded in a wider process to identify disparities, test interventions, and track progress']] },
  { id: 'hea-from-score-to-action', key: 'l6st1', verdict: 'INACCURATE', claim: 'CMS Framework Priority 2 described as "assess causes of disparities within an organization\'s own programs and operations"', sources: CMSFW,
    pairs: [['This maps directly onto Priority 2 of the CMS Framework for Health Equity 2022–2032: assess causes of disparities within an organization\'s own programs and operations, not just document their existence.',
      'It mirrors Priority 2 of the CMS Framework for Health Equity 2022–2032, in which CMS commits to assess the causes of disparities within its own programs and address inequities in its policies and operations, not just document that disparities exist.']],
    mirrorPairs: [['This maps directly to Priority 2 of the CMS Framework for Health Equity 2022–2032: assess causes of disparities within programs and operations, not just their existence.',
      'It mirrors Priority 2 of the CMS Framework for Health Equity 2022–2032, in which CMS commits to assess causes of disparities within its own programs and address inequities in its policies and operations.']] },
  { id: 'hea-from-score-to-action', key: 'l6s4h', verdict: 'FABRICATED', claim: 'heading "From Screening Data to an Anchor-Mission Committee"', sources: RUSH6,
    pairs: [['Case Study: From Screening Data to an Anchor-Mission Committee', 'Case Study: From Screening to Standing Committees']],
    mirrorPairs: [['Case study: from screening data to an anchor-mission committee', 'Case study: from screening to standing committees']] },
  { id: 'hea-from-score-to-action', key: 'l6ex1', verdict: 'FABRICATED', claim: 'Rush "formed a West Side Anchor Committee explicitly to convert what the screening and stratified quality data showed" with partners incl. "CommunityHealth"', sources: RUSH6,
    pairs: [[L6_RUSH_OLD, L6_RUSH_NEW], ['That committee is this lesson\'s governance loop made concrete: a named structure', 'Those committees are this lesson\'s governance loop made concrete: named structures'],
      ['Rush University Medical Center — West Side Anchor Committee', 'Rush University Medical Center — From Screening to Standing Committees']],
    mirrorPairs: [[L6_RUSH_OLD.replace(/’/g, "'") , L6_RUSH_NEW],
      ['That committee is the \'someone whose job it is to act\' this lesson\'s governance loop describes, made concrete.', 'Those committees are the \'someone whose job it is to act\' this lesson\'s governance loop describes, made concrete.'],
      ['Rush University Medical Center\'s West Side Anchor Committee was formed specifically to convert SDOH screening and stratified quality data into standing operational decisions with community partners.',
        'Rush University Medical Center\'s internal Anchor Mission committee, organized in January 2017, sets standing targets for local hiring, career pathways, local spending, and volunteering.'],
      ['This matches the case study directly: the committee was formed to translate what screening data showed into shared goals, referral pathways, and investment decisions with partners like Catholic Charities and the Greater Chicago Food Depository.',
        'This matches the case study (Ansell et al., NEJM Catalyst 2021): the committee owns standing targets and reports to senior leadership twice a year — a named structure whose job is to act.']] },
  { id: 'hea-from-score-to-action', key: 'l6tw', verdict: 'INACCURATE', claim: 'takeaways restate the dashboard "research finds", Priority 2 as a call on organizations, and the fabricated Rush West Side Anchor Committee role', sources: GALL + ' | ' + CMSFW + ' | ' + RUSH6,
    pairs: [['Published research on disparity dashboards finds that stratified dashboards are common, but dashboards tied to a real accountability structure that acts on the data are much rarer — measurement alone does not produce action.',
      'A 2023 Lancet Digital Health review (Gallifant et al.) found that only six of the dashboard studies it evaluated used the dashboard within a wider process to identify disparities, test interventions, or track progress toward a goal — measurement alone does not produce action.'],
      ['CMS\'s Framework for Health Equity 2022–2032 explicitly calls for assessing causes of disparities within an organization\'s own programs and operations, not only documenting that disparities exist.',
        'In Priority 2 of its Framework for Health Equity 2022–2032, CMS commits to assessing the causes of disparities within its own programs and operations, not only documenting that disparities exist — a discipline any organization can apply to its own.'],
      ['Rush University Medical Center\'s West Side Anchor Committee is a concrete, named structure that converted SDOH and quality data into standing operational decisions with community partners.',
        'Rush University Medical Center pairs routine social-needs screening (including the West Side ConnectED emergency-department collaborative) with named standing bodies — an Anchor Mission committee and a Health Equity Governance Committee — that own targets and act on what the data show.']] },
  { id: 'hea-from-score-to-action', key: 'l6qz', verdict: 'INACCURATE', claim: 'quiz explanation: literature "specifically identifies dashboards lacking a defined accountability structure as prone to sitting unused"', sources: GALL,
    pairs: [['The disparity-dashboard research literature specifically identifies dashboards lacking a defined accountability structure as prone to sitting unused', 'A 2023 review of the disparity-dashboard literature found few dashboards embedded in a wider process to identify disparities, test interventions, and track progress']] },
  { id: 'hea-from-score-to-action', key: 'src2', verdict: 'MISATTRIBUTED', claim: 'source [2] credited with the Moffitt Disparities Dashboard, which it does not mention', sources: GALL,
    pairs: [['[2] Disparity dashboards: an evaluation of the literature and framework for health equity improvement — https://pmc.ncbi.nlm.nih.gov/articles/PMC10639125/ — the measurement-without-action finding; Moffitt Cancer Center Disparities Dashboard',
      '[2] Gallifant J et al., "Disparity dashboards: an evaluation of the literature and framework for health equity improvement," Lancet Digital Health (2023) — https://pmc.ncbi.nlm.nih.gov/articles/PMC10639125/ — only six evaluated studies used a dashboard within a wider improvement process. Moffitt Cancer Center Disparities Dashboard: Quality Interactions, "What are leading organizations doing to achieve health equity" — https://www.qualityinteractions.com/blog/what-are-leading-organizations-doing-to-achieve-health-equity']] },
  { id: 'hea-from-score-to-action', key: 'src3', verdict: 'INACCURATE', claim: 'source [3] "Priority 2, assessing causes of disparities"', sources: CMSFW,
    pairs: [['— Priority 2, assessing causes of disparities', '— Priority 2, assess causes of disparities within CMS programs']] },
  { id: 'hea-from-score-to-action', key: 'src4', verdict: 'FABRICATED', claim: 'source [4] cited for a "West Side Anchor Committee" role it does not describe', sources: RUSH6,
    pairs: [['[4] Rush University Medical Center, "Health Equity as a System Strategy," NEJM Catalyst 2021 — https://catalyst.nejm.org/doi/full/10.1056/CAT.20.0674 — West Side Anchor Committee',
      '[4] Ansell DA et al., "Health Equity as a System Strategy: The Rush University Medical Center Framework," NEJM Catalyst, May 2021 — https://catalyst.nejm.org/doi/full/10.1056/CAT.20.0674 — Anchor Mission committee, Health Equity Governance Committee; Catholic Health World, "Chicago hospitals unite to address socioeconomic needs of West Side residents" (Oct 1, 2019) — West Side ConnectED']] },
);

