const HL7PB = 'HL7 Version 2 Product Brief via NLM Health Data Standards tutorial (nlm.nih.gov/oet/ed/healthdatastandards/03-300.html): "95% of U.S. healthcare organizations" and "more than 35 countries" use HL7 v2. No source located for "85% of all healthcare data exchanges" or "15 billion HL7 v2 messages annually" (searched); these are dropped.';
const MLLPPORT = 'IANA Service Name and Transport Protocol Port Number Registry (iana.org, search "hl7"): hl7 = port 2575 tcp/udp. Port 6660 is not a recognized HL7 convention (Mirth defaults to 6661); interfaces are configured per agreement.';
