const CCDAV = 'hl7.org/cda/us/ccda/package-list.json: C-CDA 3.0.0 trial-use 2024-05-18 (USCDI v4); 4.0.0 trial-use 2025-06-20 (USCDI v5); 5.0.0 trial-use 2026-06-13 (USCDI v6) = current. All are STU (trial-use), not normative. hl7.org/fhir/us/ccda/package-list.json: C-CDA on FHIR 2.0.0 trial-use published 2026-06-05 (1.2.0 was 2024-03-12).';
